contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public {
        require(caller != address(this));

        bool wasOpen = c.openToPublic();
        require(wasOpen == false);

        bool reverted;
        if (caller == address(this)) {
            try c.OpenToThePublic() { reverted = false; } catch { reverted = true; }
        } else {
            (bool s,) = address(c).call(abi.encodeWithSignature("OpenToThePublic()"));
            reverted = !s;
