        } else {
            assert(c.openToPublic() == false);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Record whether a wager call is blocked by the openToPublic gate before opening.
        // Caller is this contract (non-owner), so OpenToThePublic is expected to revert,
        // but we only use its effect on the gate as the observable.
        bool reverted;
        try c.OpenToThePublic() { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            // OpenToThePublic succeeded; the gate must now be open, so a wager with the
            // exact bet limit must be accepted (not blocked by the openToPublic modifier),
            // as long as no prior wager exists for this caller.
            bool wagerReverted;
            try c.wager{value: amount}() { wagerReverted = false; } catch { wagerReverted = true; }
            assert(!wagerReverted || c.hasPlayerWagered(address(this)));
        } else {
            // OpenToThePublic reverted; the gate must still be closed, so a wager must
            // revert unless the caller already has an outstanding wager.
            bool wagerReverted;
            try c.wager{value: amount}() { wagerReverted = false; } catch { wagerReverted = true; }
            assert(wagerReverted || c.hasPlayerWagered(address(this)));
        }
    }

    receive() external payable {}
}

